-- Pack fr — self-consumption, individual and collective: who may share, how far, how much, with which keys.
set search_path = nexgen, public, extensions;

insert into rules (code, name, section, country, regions, applies_to, statement, parameters, legal_source_code, article, url, valid_from, valid_to, published_by, notes) values
  ('fr_aci_definition', 'Individual self-consumption', 'energy_sharing', 'FR', '{}', 'site',
   'A producer consumes all or part of the electricity its installation produces on the same site, the surplus being injected or sold; individual self-consumption needs no organising entity.',
   '{}',
   'fr_code_energie', 'L. 315-1', 'https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000043213105', null, null, 'pack:fr', null),
  ('fr_acc_definition', 'Collective self-consumption: producers and consumers in one organising entity', 'energy_sharing', 'FR', '{}', 'project',
   'An operation is collective when one or more producers supply one or more final consumers, linked within one legal entity (the organising entity, personne morale organisatrice), their connection points being in the same building or, for an extended operation, within the perimeter the ministerial order sets on the low-voltage grid.',
   '{"organising_entity_required": true, "grid": "public distribution grid"}',
   'fr_code_energie', 'L. 315-2', 'https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000047296047', null, null, 'pack:fr', null),
  ('fr_acc_organising_entity', 'Any legal form may organise an operation', 'energy_sharing', 'FR', '{}', 'project',
   'The organising entity may take any legal form: an association, a cooperative, a mixed-economy company, a local authority, a social landlord, a co-ownership syndicate; it signs the convention with the distribution operator, holds the allocation key and the list of participants.',
   '{"legal_forms": ["association", "cooperative", "sem", "local_authority", "social_landlord", "co_ownership", "company"]}',
   'fr_code_energie', 'L. 315-2', 'https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000047296047', null, null, 'pack:fr', null),
  ('fr_acc_perimeter_standard', 'Extended operation: 2 km between the two furthest participants', 'energy_sharing', 'FR', '{}', 'project',
   'In an extended collective self-consumption operation, the distance between the two furthest participants is at most 2 kilometres, measured between their connection points.',
   '{"max_distance_m": 2000, "measured_between": "connection points"}',
   'fr_arrete_2019_11_21_acc', 'Article 1', 'https://www.legifrance.gouv.fr/loda/id/JORFTEXT000039417566/', '2019-11-23', null, 'pack:fr', null),
  ('fr_acc_perimeter_periurban', 'Up to 10 km when every participant is in a rural or peri-urban municipality', 'energy_sharing', 'FR', '{}', 'project',
   'By derogation granted by the minister, the distance may reach 10 kilometres when all producers and consumers are in rural or peri-urban municipalities, as the national statistics grid defines them.',
   '{"max_distance_m": 10000, "condition": "all participants in rural or peri-urban municipalities", "granted_by": "minister"}',
   'fr_arrete_2019_11_21_acc', 'Article 1, as amended on 14 October 2020', 'https://www.legifrance.gouv.fr/loda/id/JORFTEXT000039417566/', '2020-10-16', null, 'pack:fr', null),
  ('fr_acc_perimeter_rural', 'Up to 20 km when every participant is in a rural municipality', 'energy_sharing', 'FR', '{}', 'project',
   'By derogation granted by the minister, the distance may reach 20 kilometres when all producers and consumers are in rural municipalities.',
   '{"max_distance_m": 20000, "condition": "all participants in rural municipalities", "granted_by": "minister"}',
   'fr_arrete_2019_11_21_acc', 'Article 1, as amended on 14 October 2020', 'https://www.legifrance.gouv.fr/loda/id/JORFTEXT000039417566/', '2020-10-16', null, 'pack:fr', null),
  ('fr_acc_perimeter_public_entity', 'The territory of an inter-municipal body when every participant is a public service', 'energy_sharing', 'FR', '{}', 'project',
   'For an operation that includes an inter-municipal body with its own tax powers (EPCI à fiscalité propre) and whose participants all carry a public service mission or are mixed-economy companies, the perimeter is the territory of that body.',
   '{"perimeter": "territory of the EPCI", "condition": "all participants public service or SEM"}',
   'fr_arrete_2019_11_21_acc', 'Article 1 bis, added on 21 February 2025', 'https://www.legifrance.gouv.fr/loda/id/JORFTEXT000039417566/', '2025-02-22', null, 'pack:fr', 'The power ceiling of these operations (5 MW or 10 MW) differs between secondary sources: read the consolidated order before relying on it.'),
  ('fr_acc_power_cap_3mw', 'Cumulative production power below 3 MW', 'energy_sharing', 'FR', '{}', 'project',
   'The cumulative power of the production installations of an extended operation is below 3 MW in mainland France, 0.5 MW in the non-interconnected zones.',
   '{"max_power_kw_mainland": 3000, "max_power_kw_islands": 500, "exclusive": true}',
   'fr_arrete_2019_11_21_acc', 'Article 1', 'https://www.legifrance.gouv.fr/loda/id/JORFTEXT000039417566/', '2019-11-23', '2025-02-21', 'pack:fr', 'Replaced by the 5 MW ceiling on 22 February 2025.'),
  ('fr_acc_power_cap_5mw', 'Cumulative production power below 5 MW', 'energy_sharing', 'FR', '{}', 'project',
   'Since the order of 21 February 2025, the cumulative power of the production installations of an extended operation is below 5 MW in mainland France (peak power for photovoltaics), 0.5 MW in the non-interconnected zones.',
   '{"max_power_kw_mainland": 5000, "max_power_kw_islands": 500, "exclusive": true, "photovoltaic_measure": "peak power"}',
   'fr_arrete_2019_11_21_acc', 'Article 1, as amended on 21 February 2025', 'https://www.legifrance.gouv.fr/loda/id/JORFTEXT000039417566/', '2025-02-22', null, 'pack:fr', null),
  ('fr_acc_allocation_keys', 'Three allocation keys the operator applies, on the 30-minute step', 'energy_sharing', 'FR', '{}', 'project',
   'The organising entity gives the distribution operator the key that shares the production among the consumers at each 30-minute step: static (fixed shares per participant), dynamic by default (pro rata of each consumer''s consumption at the step, the operator''s algorithm), or dynamic custom (the entity''s own coefficients, transmitted for each step). The key may differ by time band.',
   '{"step": "PT30M", "keys": ["static", "dynamic_default", "dynamic_custom"], "by_time_band": true}',
   'fr_enedis_noi_cf_110e', null, 'https://www.enedis.fr/media/2910/download', null, null, 'pack:fr', null),
  ('fr_acc_convention', 'A convention with the distribution operator before the first allocation', 'energy_sharing', 'FR', '{}', 'project',
   'Before the operation starts, the organising entity signs the operator''s collective self-consumption convention: perimeter, list of connection points, key, data returned, how entries and exits are declared. The entity declares every change of key or perimeter.',
   '{"declares": ["key changes", "entries", "exits"]}',
   'fr_enedis_convention_acc', null, 'https://www.enedis.fr/media/1881/download', null, null, 'pack:fr', null),
  ('fr_acc_settlement', 'Each month the operator returns the allocated curves; the entity settles', 'energy_sharing', 'FR', '{}', 'project',
   'Each month the distribution operator computes, at the 30-minute step, the self-consumed share allocated to each consumer and the surplus of each producer, and returns these curves to the organising entity and to the suppliers; the entity or the producers invoice the allocated energy on the price they agreed, the suppliers invoice the rest, the surplus is sold under the purchase obligation or on the market.',
   '{"period": "P1M", "step": "PT30M", "returned_to": ["organising entity", "suppliers"]}',
   'fr_enedis_convention_acc', null, 'https://www.enedis.fr/media/1881/download', null, null, 'pack:fr', null);
